document.addEventListener('submit',async (event)=>{ if(event.target.matches('[data-material-form]')){ event.preventDefault(); const data=new FormData(event.target); const name=String(data.get('name')||'').trim(); const quantity=Number(data.get('quantity')); if(!name||!Number.isFinite(quantity)){toast('자재명과 수량을 입력하세요.',true);return;} const id=event.target.dataset.id; const row={name,quantity,dueDate:String(data.get('dueDate')||''),status:String(data.get('status')||'purchasing')}; const existing=state.materials.find(item=>item.id===id); if(existing) Object.assign(existing,row); else state.materials.push({id:`material-${Date.now()}`,...row}); const saved=await saveState(); if(!saved)return; $('[data-dialog]').close(); render(); toast('자재를 저장했습니다.'); return; } if(event.target.matches('[data-spare-form]')){ event.preventDefault(); const data=new FormData(event.target); const name=String(data.get('name')||'').trim(); const quantity=Number(data.get('quantity')); if(!name||!Number.isFinite(quantity)){toast('예비품명과 수량을 입력하세요.',true);return;} const id=event.target.dataset.id; const row={name,quantity,repairStatus:String(data.get('repairStatus')||'수리 필요'),startDate:String(data.get('startDate')||''),completedDate:String(data.get('completedDate')||''),memo:String(data.get('memo')||'').trim()}; const existing=state.spares.find(item=>item.id===id); if(existing) Object.assign(existing,row); else state.spares.push({id:`spare-${Date.now()}`,...row}); const saved=await saveState(); if(!saved)return; $('[data-dialog]').close(); render(); toast('예비품을 저장했습니다.'); return; } });
