  function updateVirtualStatus(connected, lastCollectedAt){ const badge=$('[data-virtual-status]'); const last=$('[data-virtual-last-collected]'); if(!badge||!last)return; badge.classList.toggle('connected',connected); badge.classList.toggle('disconnected',!connected); badge.textContent=connected?'센서 실행 중':'센서 연결 대기'; last.textContent=lastCollectedAt?`최근 수집 ${new Date(lastCollectedAt).toLocaleString('ko-KR')}`:'최근 수집 시각 없음'; }
  async function hydrateFromVirtualSensor(){ try { const [stateResponse,statusResponse]=await Promise.all([fetch('/api/virtual-sensor/state',{cache:'no-store'}),fetch('/api/virtual-sensor/status',{cache:'no-store'})]); if(!stateResponse.ok||!statusResponse.ok)throw new Error('virtual sensor api unavailable'); const remote=await stateResponse.json(); const status=await statusResponse.json(); if(Array.isArray(remote.equipment)&&remote.equipment.length){ state.equipment=remote.equipment; state.alerts=Array.isArray(remote.alerts)&&remote.alerts.length?[...new Map(remote.alerts.map(alert=>[alert.equipmentId,alert])).values()]:state.alerts; const mergedHistory={...state.historyByEquipment}; Object.entries(remote.historyByEquipment||{}).forEach(([id,rows])=>{if(Array.isArray(rows)&&rows.length){mergedHistory[id]=[...(mergedHistory[id]||[]),...rows].filter((row,index,all)=>all.findIndex(other=>other.recordedAt===row.recordedAt)===index).sort((a,b)=>String(a.recordedAt).localeCompare(String(b.recordedAt))).slice(-1000);}}); state.historyByEquipment=mergedHistory; localStorage.setItem(KEY,JSON.stringify(state)); render(); } updateVirtualStatus(Boolean(status.running),status.lastCollectedAt); } catch { updateVirtualStatus(false,null); } }
